def amicable_numbers_sum(limit):
    d = [0] * (limit + 1)
    for i in range(2, limit // 2 + 1):
        for j in range(i << 1, limit + 1, i):
            d[j] += i
    return sum(i for i in range(1, limit + 1) if d[i] != i and d[i] <= limit and d[d[i]] == i)
```

